Translate the following Java 11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 11 code you have to translate:
<original_code>
import java.util.Scanner;

public class Main {
    static char[] cs;
    static int res = 0;
    static int X = 0;
    static int n;

    static void dfs(int u, int s) {
        if (u >= n) {
            if (s % 25 == 0) res++;
            return;
        }
        int t = cs[u] - '0';
        if (t >= 0 && t <= 9) dfs(u + 1, s * 10 + t);
        else if (cs[u] == 'X') dfs(u + 1, s * 10 + X);
        else {
            if (u == n - 1) {
                dfs(u + 1, s * 10 + 5);
                dfs(u + 1, s * 10);
            } else {
                for (int i = 0; i < 10; i++) {
                    if (i == 0 && u == 0) continue;
                    dfs(u + 1, s * 10 + i);
                }
            }
        }
    }

    static void solve() {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();
        cs = input.toCharArray();
        n = cs.length;
        boolean hasX = false;
        for (char c : cs) {
            if (c == 'X') {
                hasX = true;
                break;
            }
        }
        if (cs[0] == '0' && n != 1) {
            System.out.println(0);
            return;
        }
        if (hasX) {
            for (int i = 0; i < 10; i++) {
                if (cs[0] == 'X' && n > 1 && i == 0) continue;
                X = i;
                dfs(0, 0);
            }
        } else {
            dfs(0, 0);
        }
        System.out.println(res);
        sc.close();
    }

    public static void main(String[] args) {
        solve();
    }
}
